/**
 * REVITALIS HERO 3D - Interactive 360° WebGL Bottle
 * Real-time responsive scaling on all mobile and desktop screens,
 * zero stretch/distortion via exact ResizeObserver aspect ratio sync,
 * soft dynamic contact shadow, scroll-coupled rotation, and zero idle auto-spin.
 */

(function() {
  'use strict';

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHero3D);
  } else {
    initHero3D();
  }

  function initHero3D() {
    const container = document.getElementById('hero3DStage');
    const canvas = document.getElementById('heroBottleCanvas');
    const fallbackImg = document.querySelector('.hero-fallback-img');
    const hintBadge = document.getElementById('spinHintBadge');

    if (!container || !canvas || typeof THREE === 'undefined') {
      if (fallbackImg) fallbackImg.style.display = 'block';
      if (hintBadge) hintBadge.style.display = 'none';
      return;
    }

    // Check WebGL support
    try {
      const testCanvas = document.createElement('canvas');
      const gl = testCanvas.getContext('webgl') || testCanvas.getContext('experimental-webgl');
      if (!gl) throw new Error('WebGL not supported');
    } catch (e) {
      if (fallbackImg) fallbackImg.style.display = 'block';
      if (hintBadge) hintBadge.style.display = 'none';
      return;
    }

    // Measure exact initial container dimensions
    const initialRect = container.getBoundingClientRect();
    let width = Math.round(initialRect.width) || container.clientWidth || 320;
    let height = Math.round(initialRect.height) || container.clientHeight || 440;
    if (width < 50) width = 320;
    if (height < 50) height = 440;

    // Scene & Perspective Camera
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(32, width / height, 0.1, 100);
    camera.position.set(0, 0.15, 7.8);

    // WebGL Renderer with Alpha Transparency
    const renderer = new THREE.WebGLRenderer({
      canvas: canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'high-performance'
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;
    renderer.outputEncoding = THREE.sRGBEncoding;

    // Load Textures from Base64
    const textureLoader = new THREE.TextureLoader();

    // 1. Compact Label Texture (3072x1024, calibrated 3.01:1)
    const labelImg = new Image();
    labelImg.src = 'data:image/png;base64,';
    const labelTexture = new THREE.Texture(labelImg);
    labelTexture.encoding = THREE.sRGBEncoding;
    labelTexture.wrapS = THREE.RepeatWrapping;
    labelTexture.wrapT = THREE.ClampToEdgeWrapping;
    labelImg.onload = () => {
      labelTexture.needsUpdate = true;
    };

    // 2. Realistic Soft Contact Shadow Texture (512x512)
    const shadowImg = new Image();
    shadowImg.src = 'data:image/png;base64,';
    const shadowTexture = new THREE.Texture(shadowImg);
    shadowTexture.encoding = THREE.sRGBEncoding;
    shadowImg.onload = () => {
      shadowTexture.needsUpdate = true;
    };

    // Floor Contact Shadow Mesh
    const shadowGeo = new THREE.PlaneGeometry(3.9, 3.9);
    const shadowMat = new THREE.MeshBasicMaterial({
      map: shadowTexture,
      transparent: true,
      opacity: 0.62,
      depthWrite: false
    });
    const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = -1.66;
    scene.add(shadowMesh);

    // Studio Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.85);
    scene.add(ambientLight);

    const keyLight = new THREE.DirectionalLight(0xffffff, 0.98);
    keyLight.position.set(4, 5, 5);
    scene.add(keyLight);

    const fillLight = new THREE.DirectionalLight(0xe8f4ee, 0.58);
    fillLight.position.set(-4, 2, 4);
    scene.add(fillLight);

    const rimLight = new THREE.DirectionalLight(0xfff8eb, 0.85);
    rimLight.position.set(0, 4, -5);
    scene.add(rimLight);

    // Bottle Group (rotates 360)
    const bottleGroup = new THREE.Group();
    bottleGroup.position.y = -0.05;
    scene.add(bottleGroup);

    // Materials
    const bottleWhiteMat = new THREE.MeshStandardMaterial({
      color: 0xF8FAF9,
      roughness: 0.28,
      metalness: 0.04
    });

    const goldCapMat = new THREE.MeshStandardMaterial({
      color: 0xD4AF37,
      metalness: 0.88,
      roughness: 0.24
    });

    const goldAccentMat = new THREE.MeshStandardMaterial({
      color: 0xC59B27,
      metalness: 0.82,
      roughness: 0.28
    });

    const labelMat = new THREE.MeshStandardMaterial({
      map: labelTexture,
      roughness: 0.32,
      metalness: 0.03
    });

    // 1. Bottle Body (Cylinder with label)
    // Cylinder: radius: 1.15, height: 2.4 (Circumference 7.225 / 2.4 = 3.01 ratio)
    const bodyGeo = new THREE.CylinderGeometry(1.15, 1.15, 2.4, 64, 1, true);
    const bodyMesh = new THREE.Mesh(bodyGeo, labelMat);
    bodyMesh.position.y = -0.30;
    bodyMesh.rotation.y = Math.PI;
    bottleGroup.add(bodyMesh);

    // 2. Rounded Base
    const baseGeo = new THREE.CylinderGeometry(1.149, 1.10, 0.16, 64);
    const baseMesh = new THREE.Mesh(baseGeo, bottleWhiteMat);
    baseMesh.position.y = -1.58;
    bottleGroup.add(baseMesh);

    const bottomCapGeo = new THREE.CylinderGeometry(1.10, 1.02, 0.06, 64);
    const bottomCapMesh = new THREE.Mesh(bottomCapGeo, bottleWhiteMat);
    bottomCapMesh.position.y = -1.64;
    bottleGroup.add(bottomCapMesh);

    // 3. Shoulder Taper (Curved dome from body to neck)
    const shoulderGeo = new THREE.CylinderGeometry(0.86, 1.149, 0.42, 64);
    const shoulderMesh = new THREE.Mesh(shoulderGeo, bottleWhiteMat);
    shoulderMesh.position.y = 1.11;
    bottleGroup.add(shoulderMesh);

    // Upper Shoulder Ring
    const shoulderRingGeo = new THREE.CylinderGeometry(0.85, 0.86, 0.08, 64);
    const shoulderRingMesh = new THREE.Mesh(shoulderRingGeo, bottleWhiteMat);
    shoulderRingMesh.position.y = 1.34;
    bottleGroup.add(shoulderRingMesh);

    // 4. Neck
    const neckGeo = new THREE.CylinderGeometry(0.82, 0.85, 0.26, 64);
    const neckMesh = new THREE.Mesh(neckGeo, bottleWhiteMat);
    neckMesh.position.y = 1.47;
    bottleGroup.add(neckMesh);

    // 5. Metallic Gold Cap
    // Lower Gold Ring
    const capRingGeo = new THREE.CylinderGeometry(0.92, 0.92, 0.08, 64);
    const capRingMesh = new THREE.Mesh(capRingGeo, goldAccentMat);
    capRingMesh.position.y = 1.61;
    bottleGroup.add(capRingMesh);

    // Main Gold Cap
    const capGeo = new THREE.CylinderGeometry(0.94, 0.94, 0.56, 64);
    const capMesh = new THREE.Mesh(capGeo, goldCapMat);
    capMesh.position.y = 1.91;
    bottleGroup.add(capMesh);

    // Cap Top Bevel
    const capTopGeo = new THREE.CylinderGeometry(0.91, 0.94, 0.06, 64);
    const capTopMesh = new THREE.Mesh(capTopGeo, goldCapMat);
    capTopMesh.position.y = 2.21;
    bottleGroup.add(capTopMesh);

    // Interaction & Animation Physics
    let time = 0;
    let targetRotationY = 0;
    let currentRotationY = 0;
    let targetTiltX = 0;
    let currentTiltX = 0;
    let targetTiltZ = 0;
    let currentTiltZ = 0;
    let isDragging = false;
    let pointerStartX = 0;
    let pointerStartY = 0;
    let prevScrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    let hasInteracted = false;
    let currentBaseScale = 1.0;

    // Interaction Listeners (Mouse & Touch Drag)
    function onPointerDown(e) {
      isDragging = true;
      pointerStartX = e.clientX || (e.touches && e.touches[0].clientX) || 0;
      pointerStartY = e.clientY || (e.touches && e.touches[0].clientY) || 0;
      container.style.cursor = 'grabbing';
      if (hintBadge && !hasInteracted) {
        hintBadge.style.opacity = '0.3';
      }
    }

    function onPointerMove(e) {
      const clientX = e.clientX || (e.touches && e.touches[0].clientX) || 0;
      const clientY = e.clientY || (e.touches && e.touches[0].clientY) || 0;

      // Mouse Parallax Tilt
      if (!e.touches) {
        const rect = container.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
          const nx = (clientX - rect.left) / rect.width - 0.5;
          const ny = (clientY - rect.top) / rect.height - 0.5;
          targetTiltX = ny * 0.14;
          targetTiltZ = -nx * 0.12;
        }
      }

      if (!isDragging) return;

      const deltaX = clientX - pointerStartX;
      pointerStartX = clientX;
      pointerStartY = clientY;

      targetRotationY += deltaX * 0.012;
      hasInteracted = true;
    }

    function onPointerUp() {
      if (isDragging) {
        isDragging = false;
        container.style.cursor = 'grab';
        if (hintBadge && hasInteracted) {
          setTimeout(() => {
            hintBadge.style.opacity = '0';
            hintBadge.style.pointerEvents = 'none';
          }, 1800);
        }
      }
    }

    container.addEventListener('mousedown', onPointerDown);
    window.addEventListener('mousemove', onPointerMove);
    window.addEventListener('mouseup', onPointerUp);

    container.addEventListener('touchstart', onPointerDown, { passive: true });
    window.addEventListener('touchmove', onPointerMove, { passive: true });
    window.addEventListener('touchend', onPointerUp);

    container.style.cursor = 'grab';

    // Alive Scroll Coupling:
    // Bottle does NOT spin autonomously, but spins continuously and smoothly as user scrolls
    window.addEventListener('scroll', () => {
      const currentScrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
      const delta = currentScrollY - prevScrollY;
      prevScrollY = currentScrollY;

      // Rotate continuously in proportion to scroll delta
      targetRotationY += delta * 0.0048;

      // Dynamic physical tilt leaning into the scroll direction
      targetTiltZ = Math.max(-0.09, Math.min(0.09, delta * 0.0018));

      hasInteracted = true;
      if (hintBadge) {
        hintBadge.style.opacity = '0';
        hintBadge.style.pointerEvents = 'none';
      }
    }, { passive: true });

    // Precision Responsive Resize System (Guarantees zero stretching on ANY mobile screen)
    function syncDimensions() {
      const rect = container.getBoundingClientRect();
      let w = Math.round(rect.width);
      let h = Math.round(rect.height);
      if (w < 60) w = 300;
      if (h < 60) h = 400;

      // Camera aspect matches display aspect ratio with 100% precision
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h, true);

      // Adaptive Mobile Scaling:
      // Keep the 3D bottle prominent, bold, and realistically sized on mobile screens
      if (w < 380 || h < 460) {
        const scaleByH = h / 450;
        currentBaseScale = Math.min(1.0, Math.max(0.70, scaleByH * 0.88));
      } else {
        currentBaseScale = 1.0;
      }
      
      bottleGroup.scale.set(currentBaseScale, currentBaseScale, currentBaseScale);
    }

    // Observe container size changes directly (responsive to mobile orientation, layout reflow, zoom)
    if (window.ResizeObserver) {
      const resizeObserver = new ResizeObserver(() => {
        syncDimensions();
      });
      resizeObserver.observe(container);
    } else {
      window.addEventListener('resize', syncDimensions);
    }

    // Initial sync
    syncDimensions();

    // Render Animation Loop
    function animate() {
      requestAnimationFrame(animate);

      // NOTICE: NO IDLE AUTO-SPIN!
      // The bottle only spins when the user scrolls or drags.

      // Smooth Spring Damping
      currentRotationY += (targetRotationY - currentRotationY) * 0.082;
      currentTiltX += (targetTiltX - currentTiltX) * 0.06;
      currentTiltZ += (targetTiltZ - currentTiltZ) * 0.06;

      // Dynamic tilt decay returning softly to upright
      targetTiltZ *= 0.94;

      // Subtle Living Float Breath
      time += 0.018;
      const floatY = Math.sin(time) * 0.035;
      bottleGroup.position.y = -0.05 + floatY;

      // Realistic Responsive Contact Shadow:
      // Shadow scales organically with bottle scale and vertical float
      const dynamicShadowScale = currentBaseScale * (1.0 - floatY * 0.4);
      shadowMesh.scale.set(dynamicShadowScale, dynamicShadowScale, 1);
      shadowMat.opacity = Math.max(0.20, 0.62 - floatY * 1.35);
      shadowMesh.rotation.z = -currentRotationY * 0.05 + currentTiltZ * 0.35;
      shadowMesh.position.x = currentTiltZ * 0.35;
      shadowMesh.position.z = -currentTiltX * 0.25;

      // Apply Rotations
      bottleGroup.rotation.y = currentRotationY;
      bottleGroup.rotation.x = currentTiltX;
      bottleGroup.rotation.z = currentTiltZ;

      renderer.render(scene, camera);
    }

    animate();
  }
})();
